const body = $input.first().json.body;
const data = body.data;
const updatedFrom = body.updatedFrom || {};

// Issue info
const issueUrl = data.url || `https://linear.app/bunluxsa/issue/${data.identifier}`;
const issueTitle = data.title || 'Unknown Issue';
const issueId = data.identifier || data.id || 'Unknown';

// Status info
const newStatus = data.state?.name || 'Unknown';
const oldStatusName = updatedFrom.stateName || null;

// Actor (who made the change)
const actor = body.actor?.name || 'Someone';

// Status color mapping
const statusColors = {
  'Todo': 9807270,           // #95A5A6 grey
  'In Progress': 16750848,   // #FF9900 orange  
  'In Review': 3447003,      // #3498DB blue
  'Done': 5763719,           // #57F287 green
  'Cancelled': 10066329,     // #99AAB5 grey
  'Backlog': 7506394,        // #72757A dark grey
  'รอ PM Review': 16776960,  // #FFFF00 yellow
  'กำลังดำเนินการ': 16750848, // orange
  'เสร็จแล้ว': 5763719,      // green
};

const color = statusColors[newStatus] || 8073671; // default purple

// Status emoji mapping
const statusEmoji = {
  'Todo': '⬜',
  'In Progress': '🟡',
  'In Review': '🔵',
  'Done': '✅',
  'Cancelled': '❌',
  'Backlog': '📋',
  'รอ PM Review': '🟡',
  'กำลังดำเนินการ': '🟡',
  'เสร็จแล้ว': '✅',
};

const emoji = statusEmoji[newStatus] || '🔄';

// Build status change text
const statusChange = oldStatusName
  ? `${oldStatusName} → **${newStatus}**`
  : `→ **${newStatus}**`;

// Build embed fields
const fields = [
  {
    name: '🔄 Status Change',
    value: statusChange,
    inline: false
  }
];

if (data.assignee?.name) {
  fields.push({
    name: '👤 Assignee',
    value: data.assignee.name,
    inline: true
  });
}

if (data.priority !== undefined) {
  const priorityMap = { 0: 'No Priority', 1: '🔴 Urgent', 2: '🟠 High', 3: '🟡 Medium', 4: '🔵 Low' };
  fields.push({
    name: '⚡ Priority',
    value: priorityMap[data.priority] || 'Unknown',
    inline: true
  });
}

if (data.team?.name) {
  fields.push({
    name: '🏷️ Team',
    value: data.team.name,
    inline: true
  });
}

// Build Discord payload
const payload = {
  embeds: [
    {
      author: {
        name: `${emoji} ${actor} updated status`
      },
      title: `${issueId}: ${issueTitle}`,
      url: issueUrl,
      color: color,
      fields: fields,
      footer: {
        text: 'Linear • Status Update'
      },
      timestamp: new Date().toISOString()
    }
  ]
};

return { payload: JSON.stringify(payload) };
